pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address logger, bool status) public {
        // _contractOwner is uninitialized, hence address(0) is the only caller
        // permitted by onlyOwner. Keep the domain wide: any logger address
        // distinct from the owner (owner == caller here).
        vm.assume(logger != address(0));

        // owner (address(0)) approves an arbitrary logger
        vm.prank(address(0));
        c.setApprovedLogger(logger, status);

        // General rule: the caller's own approval flag is untouched by a call
        // that targets a different key — it must remain false for any logger
        // other than the caller itself. The mutant writes the status to
        // msg.sender, so the owner's flag becomes true when status is true.
        assertTrue(!c.approvedLoggers(address(0)), "caller's own entry must stay false when approving a different logger");
    }
}

