pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(this); // deployer is the contract owner
    }

    function testFuzz_property(address logger, address keep, bool status) public {
        vm.assume(logger != address(0));
        // Owner grants or revokes approval for the fuzzed logger.
        vm.prank(owner);
        c.setApprovedLogger(logger, status);

        // General rule: the logger's ability to log mirrors exactly the
        // status that was set — approved loggers can log, disapproved ones cannot.
        vm.prank(logger);
        bool logged = c.logCreated(keep);

        assertTrue(logged == status, "log success must equal granted status");
    }
}

