contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address logger, bool status) public payable {
        // Narrow inputs: the target logger must not already be approved, so any
        // change to its approval status can only come from this call.
        require(c.approvedLoggers(logger) == false);
        bool reverted;
        try c.setApprovedLogger(logger, status) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.approvedLoggers(logger) == false);
    }
    receive() external payable {}
}

