contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a) public {
        require(true);
        bool obs = c.approvedToLog(a);
        // msg.sender == address(this), so logFunded's return reflects address(this)'s status.
        // To make the comparison apples-to-apples, choose a == address(this) via the caller;
        // approvedToLog(a) and the log call both reflect the same mapping entry when a == address(this).
        bool ok = c.logFunded();
        assert(ok == obs || a != address(this));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address a) public payable {
        require(true);
        bool obs = c.approvedToLog(a);
        bool flagged = c.approvedLoggers(a);
        assert(obs == flagged);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _script, uint256 _fee, bytes memory _outpoint) public {
        require(c.approvedToLog(address(this)) == false, "caller already approved");
        bool ok = c.logRedemptionRequested(_requester, _digest, _utxoSize, _script, _fee, _outpoint);
        assert(ok == false);
    }
